PRAGMA foreign_keys=ON;
CREATE TABLE IF NOT EXISTS companies (id TEXT PRIMARY KEY, legal_name TEXT NOT NULL, trading_name TEXT NOT NULL, registration_no TEXT DEFAULT '', vat_no TEXT DEFAULT '', vat_mode TEXT NOT NULL DEFAULT 'non_vat' CHECK(vat_mode IN ('non_vat','vat_vendor')), address TEXT DEFAULT '', phone TEXT DEFAULT '', email TEXT DEFAULT '', bank_details TEXT DEFAULT '', terms TEXT DEFAULT '', accent TEXT DEFAULT '#e9aa16', logo_data TEXT DEFAULT '', created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS users (id TEXT PRIMARY KEY, company_id TEXT NOT NULL REFERENCES companies(id), name TEXT NOT NULL, username TEXT NOT NULL UNIQUE, password_salt TEXT NOT NULL, password_hash TEXT NOT NULL, role TEXT NOT NULL CHECK(role IN('owner','manager','reception','estimator','workshop','technician','accounts')), active INTEGER NOT NULL DEFAULT 1, created_at TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS idx_users_company ON users(company_id);
CREATE TABLE IF NOT EXISTS sessions (token_hash TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id), expires_at TEXT NOT NULL, created_at TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS idx_sessions_user ON sessions(user_id);
CREATE TABLE IF NOT EXISTS login_attempts (identifier TEXT PRIMARY KEY, attempts INTEGER NOT NULL DEFAULT 0, blocked_until TEXT DEFAULT '', updated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS customers (id TEXT PRIMARY KEY, company_id TEXT NOT NULL REFERENCES companies(id), name TEXT NOT NULL, phone TEXT DEFAULT '', email TEXT DEFAULT '', address TEXT DEFAULT '', customer_type TEXT NOT NULL DEFAULT 'individual', created_at TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS idx_customers_company ON customers(company_id,created_at DESC);
CREATE TABLE IF NOT EXISTS vehicles (id TEXT PRIMARY KEY, company_id TEXT NOT NULL REFERENCES companies(id), customer_id TEXT NOT NULL REFERENCES customers(id), registration TEXT NOT NULL, vin TEXT DEFAULT '', make TEXT DEFAULT '', model TEXT DEFAULT '', year INTEGER, colour TEXT DEFAULT '', mileage INTEGER, engine_no TEXT DEFAULT '', created_at TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS idx_vehicles_company ON vehicles(company_id,registration);
CREATE TABLE IF NOT EXISTS jobs (id TEXT PRIMARY KEY, company_id TEXT NOT NULL REFERENCES companies(id), customer_id TEXT NOT NULL REFERENCES customers(id), vehicle_id TEXT NOT NULL REFERENCES vehicles(id), reference TEXT NOT NULL, damage TEXT NOT NULL DEFAULT '', intake_notes TEXT DEFAULT '', accessories TEXT DEFAULT '', fuel_level TEXT DEFAULT '', insurer TEXT DEFAULT '', claim_no TEXT DEFAULT '', excess_cents INTEGER NOT NULL DEFAULT 0, received_at TEXT NOT NULL, expected_at TEXT DEFAULT '', stage TEXT NOT NULL DEFAULT 'received', technician_id TEXT, assigned_to TEXT DEFAULT '', qc_checks TEXT DEFAULT '', qc_notes TEXT DEFAULT '', completed_at TEXT DEFAULT '', handed_to TEXT DEFAULT '', handed_at TEXT DEFAULT '', created_by TEXT NOT NULL, UNIQUE(company_id,reference));
CREATE INDEX IF NOT EXISTS idx_jobs_company ON jobs(company_id,received_at DESC);
CREATE TABLE IF NOT EXISTS job_events (id TEXT PRIMARY KEY, company_id TEXT NOT NULL, job_id TEXT NOT NULL REFERENCES jobs(id), stage TEXT NOT NULL, note TEXT DEFAULT '', actor_id TEXT NOT NULL, at TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS idx_job_events ON job_events(company_id,job_id,at DESC);
CREATE TABLE IF NOT EXISTS photos (id TEXT PRIMARY KEY, company_id TEXT NOT NULL, job_id TEXT NOT NULL REFERENCES jobs(id), name TEXT NOT NULL DEFAULT 'Damage photo', data TEXT NOT NULL, uploaded_by TEXT NOT NULL, created_at TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS idx_photos_job ON photos(company_id,job_id);
CREATE TABLE IF NOT EXISTS sequences (company_id TEXT NOT NULL, kind TEXT NOT NULL, n INTEGER NOT NULL DEFAULT 0, PRIMARY KEY(company_id,kind));
CREATE TABLE IF NOT EXISTS estimates (id TEXT PRIMARY KEY, company_id TEXT NOT NULL, job_id TEXT NOT NULL REFERENCES jobs(id), reference TEXT NOT NULL, version INTEGER NOT NULL DEFAULT 1, assessment TEXT DEFAULT '', vat_rate INTEGER NOT NULL DEFAULT 0, subtotal_cents INTEGER NOT NULL DEFAULT 0, vat_cents INTEGER NOT NULL DEFAULT 0, total_cents INTEGER NOT NULL DEFAULT 0, status TEXT NOT NULL DEFAULT 'draft' CHECK(status IN ('draft','submitted','approved','declined')), approved_by TEXT DEFAULT '', approved_at TEXT DEFAULT '', created_by TEXT NOT NULL, created_at TEXT NOT NULL, UNIQUE(company_id,reference));
CREATE INDEX IF NOT EXISTS idx_estimates_company ON estimates(company_id,created_at DESC);
CREATE TABLE IF NOT EXISTS estimate_lines (id TEXT PRIMARY KEY, estimate_id TEXT NOT NULL REFERENCES estimates(id), category TEXT NOT NULL, description TEXT NOT NULL, qty_milli INTEGER NOT NULL, unit_cents INTEGER NOT NULL, line_cents INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS invoices (id TEXT PRIMARY KEY, company_id TEXT NOT NULL, estimate_id TEXT NOT NULL UNIQUE REFERENCES estimates(id), job_id TEXT NOT NULL REFERENCES jobs(id), reference TEXT NOT NULL, subtotal_cents INTEGER NOT NULL, vat_cents INTEGER NOT NULL, total_cents INTEGER NOT NULL, paid_cents INTEGER NOT NULL DEFAULT 0, status TEXT NOT NULL DEFAULT 'unpaid', issued_at TEXT NOT NULL, issued_by TEXT NOT NULL, UNIQUE(company_id,reference));
CREATE INDEX IF NOT EXISTS idx_invoices_company ON invoices(company_id,issued_at DESC);
CREATE TABLE IF NOT EXISTS invoice_lines (id TEXT PRIMARY KEY, invoice_id TEXT NOT NULL REFERENCES invoices(id), category TEXT NOT NULL, description TEXT NOT NULL, qty_milli INTEGER NOT NULL, unit_cents INTEGER NOT NULL, line_cents INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS payments (id TEXT PRIMARY KEY, company_id TEXT NOT NULL, invoice_id TEXT NOT NULL REFERENCES invoices(id), method TEXT NOT NULL CHECK(method IN ('cash','card','eft')), amount_cents INTEGER NOT NULL CHECK(amount_cents>0), reference TEXT NOT NULL, actor_id TEXT NOT NULL, received_at TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS idx_payments_invoice ON payments(invoice_id);
CREATE TABLE IF NOT EXISTS audit (id TEXT PRIMARY KEY, company_id TEXT NOT NULL, actor_id TEXT NOT NULL, action TEXT NOT NULL, entity TEXT NOT NULL, entity_id TEXT NOT NULL, details TEXT DEFAULT '', at TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS idx_audit_company ON audit(company_id,at DESC);
